def _load_module(path, name):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


chunker_mod = _load_module(CHUNKER, "chunk_article_module")
spellcheck_mod = _load_module(SPELLCHECK, "spellcheck_candidates_module")

HSPELL_AVAILABLE = shutil.which("hspell") is not None


def run_script(script, *args, env=None):
    return subprocess.run(
        [sys.executable, script, *args],
        capture_output=True,
        text=True,
        timeout=30,
        env=env,
    )


class TestChunkArticle(unittest.TestCase):
    def _chunk(self, text, chunk_words):
        return chunker_mod.chunk_article(text, chunk_words)

    def test_chunk_bounds_never_exceed_chunk_words_for_prose(self):
        # Five one-sentence paragraphs of 6 words each under a single
        # heading; a chunkWords cap of 10 must never pack more than one
        # paragraph per chunk (6+6 > 10), so every chunk stays <= 10 words.
        paragraphs = [f"word{i} word{i} word{i} word{i} word{i} word{i}" for i in range(5)]
        text = "## Heading\n\n" + "\n\n".join(paragraphs) + "\n"
        chunks = self._chunk(text, chunk_words=10)
        self.assertGreater(len(chunks), 1)
        for chunk in chunks:
            self.assertLessEqual(len(chunk["text"].split()), 10)

    def test_chunk_packs_multiple_short_paragraphs_together(self):
        # Two short paragraphs (3 words each) under a generous cap (1200)
        # should pack into a single chunk rather than splitting needlessly.
        text = "## Heading\n\none two three\n\nfour five six\n"
        chunks = self._chunk(text, chunk_words=1200)
        self.assertEqual(len(chunks), 1)
        self.assertIn("one two three", chunks[0]["text"])
        self.assertIn("four five six", chunks[0]["text"])

    def test_start_line_round_trips_against_source(self):
        text = (
            "# Title\n"
            "\n"
            "## Section A\n"
            "\n"
            "First paragraph line one.\n"
            "First paragraph line two.\n"
            "\n"
            "Second paragraph.\n"
            "\n"
            "## Section B\n"
            "\n"
            "Third paragraph over here with more words to say something.\n"
        )
        source_lines = text.splitlines()
        chunks = self._chunk(text, chunk_words=5)
        self.assertGreater(len(chunks), 0)
        for chunk in chunks:
            start, end = chunk["startLine"], chunk["endLine"]
            self.assertGreaterEqual(start, 1)
            self.assertLessEqual(end, len(source_lines))
            self.assertLessEqual(start, end)
            expected = "\n".join(source_lines[start - 1 : end])
            self.assertEqual(chunk["text"], expected)

    def test_heading_never_merges_across_sections(self):
        text = "## A\n\npara a\n\n## B\n\npara b\n"
        chunks = self._chunk(text, chunk_words=1200)
        headings = {c["heading"] for c in chunks}
        self.assertEqual(headings, {"A", "B"})
        for c in chunks:
            if c["heading"] == "A":
                self.assertNotIn("para b", c["text"])
            else:
                self.assertNotIn("para a", c["text"])

    def test_fenced_code_block_never_split_across_chunks(self):
        text = (
            "## Sec\n"
            "\n"
            "intro paragraph\n"
            "\n"
            "```\n"
            "line one of code\n"
            "line two of code\n"
            "line three of code\n"
            "```\n"
            "\n"
            "outro paragraph\n"
        )
        # A tiny cap forces packing decisions around the fence; the fence
        # must still land whole in exactly one chunk.
        chunks = self._chunk(text, chunk_words=2)
        fence_chunks = [c for c in chunks if "```" in c["text"]]
        self.assertEqual(len(fence_chunks), 1)
        fence_text = fence_chunks[0]["text"]
        self.assertEqual(fence_text.count("```"), 2)
        self.assertIn("line one of code", fence_text)
        self.assertIn("line two of code", fence_text)
        self.assertIn("line three of code", fence_text)

    def test_markdown_table_never_split_across_chunks(self):
        text = (
            "## Sec\n"
            "\n"
            "before table\n"
            "\n"
            "| a | b |\n"
            "|---|---|\n"
            "| 1 | 2 |\n"
            "| 3 | 4 |\n"
            "\n"
            "after table\n"
        )
        chunks = self._chunk(text, chunk_words=2)
        table_chunks = [c for c in chunks if "| a | b |" in c["text"]]
        self.assertEqual(len(table_chunks), 1)
        table_text = table_chunks[0]["text"]
        self.assertIn("|---|---|", table_text)
        self.assertIn("| 1 | 2 |", table_text)
        self.assertIn("| 3 | 4 |", table_text)

    def test_footnote_definition_never_split_across_chunks(self):
        text = (
            "## Sec\n"
            "\n"
            "body paragraph\n"
            "\n"
            "[^1]: A footnote definition\n"
            "    continued on an indented line\n"
            "\n"
            "next paragraph\n"
        )
        chunks = self._chunk(text, chunk_words=2)
        fn_chunks = [c for c in chunks if "[^1]:" in c["text"]]
        self.assertEqual(len(fn_chunks), 1)
        self.assertIn("continued on an indented line", fn_chunks[0]["text"])

    def test_chunk_words_read_from_thresholds_json_not_inlined(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            input_path = os.path.join(tmpdir, "article.md")
            thresholds_path = os.path.join(tmpdir, "thresholds.json")
            with open(input_path, "w", encoding="utf-8") as fh:
                fh.write("## Sec\n\n" + " ".join(f"w{i}" for i in range(20)) + "\n")
            with open(thresholds_path, "w", encoding="utf-8") as fh:
                json.dump({"proofread": {"chunkWords": 5}}, fh)
            proc = run_script(CHUNKER, "--input", input_path, "--thresholds", thresholds_path)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        chunks = json.loads(proc.stdout)
        # 20 words with a cap of 5 in one un-splittable paragraph: the
        # paragraph itself is the finest split unit, so it stays whole in
        # one (over-cap) chunk rather than being sentence-split.
        self.assertEqual(len(chunks), 1)
        self.assertEqual(len(chunks[0]["text"].split()), 20)

    def test_cli_missing_input_exits_nonzero(self):
        proc = run_script(CHUNKER, "--input", "/no/such/file.md")
        self.assertNotEqual(proc.returncode, 0)


class TestSpellcheckWrapperNoChecker(unittest.TestCase):
    def test_exits_zero_with_skipped_payload_when_hspell_missing(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            input_path = os.path.join(tmpdir, "article.md")
            with open(input_path, "w", encoding="utf-8") as fh:
                fh.write("שלום עולם\n")
            # Simulate hspell absence: PATH with no directory containing it.
            fake_path_dir = os.path.join(tmpdir, "empty-bin")
            os.makedirs(fake_path_dir)
            env = dict(os.environ)
            env["PATH"] = fake_path_dir
            proc = run_script(SPELLCHECK, "--input", input_path, env=env)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        self.assertEqual(json.loads(proc.stdout), {"skipped": "no checker"})


class TestSpellcheckAllowlist(unittest.TestCase):
    def test_load_allowlist_contains_seeded_ktiv_male_tokens(self):
        allowlist = spellcheck_mod.load_allowlist(ALLOWLIST)
        for token in ("אמיתי", "האמיתי", "איתו", "אזי", "האוכלוסיה"):
            self.assertIn(token, allowlist)

    def test_allowlisted_tokens_are_dropped_from_candidates(self):
        # Build a fake allowlist and a fake "hspell" that flags every
        # Hebrew-looking token it receives, to isolate the allowlist-drop
        # behavior from a real hspell install.
        with tempfile.TemporaryDirectory() as tmpdir:
            fake_allowlist = os.path.join(tmpdir, "allow.txt")
            with open(fake_allowlist, "w", encoding="utf-8") as fh:
                fh.write("# comment line\nאיתו\n")

            allowlist = spellcheck_mod.load_allowlist(fake_allowlist)

            fake_hspell = _make_fake_hspell_flag_all(tmpdir)
            candidates = spellcheck_mod.generate_candidates(
                text="איתו שלום\n",
                hspell_bin=fake_hspell,
                allowlist=allowlist,
            )
        tokens = [c["token"] for c in candidates]
        self.assertNotIn("איתו", tokens)
        self.assertIn("שלום", tokens)


def _make_fake_hspell_flag_all(tmpdir):
    """A stand-in hspell -a that flags every whitespace token it receives,
    used to test allowlist-drop logic without depending on a real install."""
    script_path = os.path.join(tmpdir, "fake_hspell_flag_all.py")
    with open(script_path, "w", encoding="utf-8") as fh:
        fh.write(
            "import sys\n"
            "data = sys.stdin.buffer.read().decode('iso-8859-8', errors='ignore')\n"
            "out = ['@(#) fake hspell']\n"
            "for line in data.split(chr(10)):\n"
            "    tokens = line.split()\n"
            "    for tok in tokens:\n"
            "        out.append('& ' + tok + ' 1 0: ' + tok)\n"
            "    out.append('')\n"
            "sys.stdout.write(chr(10).join(out) + chr(10))\n"
        )
    wrapper_path = os.path.join(tmpdir, "hspell")
    with open(wrapper_path, "w", encoding="utf-8") as fh:
        fh.write(f"#!{sys.executable}\n")
        fh.write(f"import runpy\nrunpy.run_path({script_path!r}, run_name='__main__')\n")
    os.chmod(wrapper_path, 0o755)
    return wrapper_path


class TestSpellcheckEncodingRegression(unittest.TestCase):
    """Regression coverage for the Phase 0 truncation bug: a naive
    `iconv -f UTF-8 -t ISO-8859-8` aborts at the first niqqud or
    geresh/gershayim, after which hspell silently scores a truncated
    document. This measured 2, then 4, then 10 flags off the same 60-flag
    vocabulary before the fix -- assert the fed/accounted counts match."""

    def setUp(self):
        if not HSPELL_AVAILABLE:
            self.skipTest("hspell not installed; encoding regression needs the real binary")

    def test_niqqud_and_geresh_input_is_not_truncated(self):
        # Every line carries niqqud AND a geresh/gershayim-bearing token --
        # exactly the combination a plain iconv round-trip aborts on.
        text = (
            "שָׁלוֹם עוֹלָם הרמב״ם צה״ל\n"
            "בְּרֵאשִׁית בָּרָא אֱלֹהִים הרמב׳\n"
            "לָשׁוֹן עִבְרִית מְדֻקְדֶּקֶת פרופ׳\n"
        )
        source_lines = text.splitlines()
        normalized = [spellcheck_mod._normalize_for_hspell(line) for line in source_lines]
        fed_tokens = [spellcheck_mod._tokenize(nl) for nl in normalized]
        fed_total = sum(len(t) for t in fed_tokens)
        self.assertGreater(fed_total, 0)

        candidates = spellcheck_mod.generate_candidates(
            text=text,
            hspell_bin=shutil.which("hspell"),
            allowlist=set(),
        )
        # The invariant the function itself enforces (raises on mismatch)
        # already proves no truncation happened, since this call returned
        # instead of raising. Additionally confirm hspell was actually fed
        # every line's worth of tokens by cross-checking against the same
        # normalize+tokenize path used internally.
        self.assertIsInstance(candidates, list)
        for c in candidates:
            self.assertIn(c["line"], range(1, len(source_lines) + 1))

    def test_abbreviation_with_gershayim_not_shredded_into_phantom_flag(self):
        # הרמב״ם as one token (geresh mapped to ASCII quote first) should
        # not appear truncated to הרמב as a separate flagged token purely
        # because of stripped punctuation.
        text = "ספר הרמב״ם ידוע לכולם\n"
        candidates = spellcheck_mod.generate_candidates(
            text=text,
            hspell_bin=shutil.which("hspell"),
            allowlist=set(),
        )
        tokens = [c["token"] for c in candidates]
        self.assertNotIn("הרמב", tokens)


